import { MervPluginStepPayload, MervAttachedFile, MervPlaywrightScreenshotHookParams, MervPageLike } from 'merv-client';

interface MervCucumberFormatterOptions {
    /** Override directory to find {@code merv.properties} (default {@link process.cwd}). */
    cwd?: string;
}
/**
 * Cucumber-js formatter plugin — register in {@code cucumber.js}:
 *
 * @example
 * ```js
 * export default {
 *   format: ['merv-client/cucumber-formatter'],
 *   formatOptions: { merv: {} },
 * };
 * ```
 */
declare const mervCucumberFormatter: {
    type: "formatter";
    optionsKey: string;
    formatter({ on, options, }: {
        on: (event: "message", handler: (envelope: Record<string, unknown>) => void) => void;
        options?: MervCucumberFormatterOptions;
    }): void;
};

/**
 * Custom MERV report steps for Cucumber-js step definitions (Java {@code MervReporter} parity).
 *
 * @example
 * ```js
 * import { MervReporter } from 'merv-client';
 *
 * Then('I verify the title', async function () {
 *   await MervReporter.validation('Page title', 'Home', await this.page.title());
 * });
 * ```
 */
declare class MervReporter {
    static info(str: string): Promise<void>;
    static testdata(stepName: string, data: string): Promise<void>;
    static testdataFile(stepName: string, filePath: string): Promise<void>;
    static validation(stepName: string, expected: string, actual: string, screenshot?: boolean): Promise<void>;
    /**
     * Low-level custom step (Java {@code MervPluginSteps.addStep} parity).
     *
     * @param stepType {@code testdata} | {@code assertion} | {@code information}
     */
    static addStep(stepName: string, stepType: string, expected?: string | null, actual?: string | null, testdata?: string | null, prereq?: string | null, screenshot?: boolean): Promise<void>;
    static addCustomStep(stepName: string, status?: string, errorMessage?: string | null): Promise<void>;
}

interface CucumberScenarioStart {
    testCaseStartedId: string;
    name: string;
    tags: string[];
    description?: string | null;
    /** Feature file URI / path (for summary counts). */
    featureUri?: string | null;
}
interface CucumberStepFinish {
    testCaseStartedId: string;
    testStepId: string;
    stepText: string;
    status: string;
    errorMessage?: string | null;
    startedAt?: string;
    finishedAt?: string;
    /** PNG from AfterStep — consumed synchronously in the formatter before async work. */
    prefetchedScreenshot?: Buffer | null;
}
/**
 * One MERV suite per Cucumber run; scenarios map to test cases (parallel-safe in memory).
 */
declare class MervCucumberSession {
    private readonly cfg;
    private readonly local;
    private readonly server;
    private readonly scenarios;
    private readonly completed;
    private readonly featureUris;
    private readonly startedAtMs;
    private finalized;
    private constructor();
    static open(cwd?: string): Promise<MervCucumberSession>;
    /** Local run folder path for saving testdata file attachments. */
    getLocalRunDir(): string | null;
    onScenarioStart(input: CucumberScenarioStart): Promise<void>;
    onStepFinish(input: CucumberStepFinish): Promise<void>;
    /**
     * Programmatic custom step from {@link MervReporter} inside Cucumber step definitions.
     */
    addPluginStep(testCaseStartedId: string, payload: MervPluginStepPayload, options?: {
        screenshot?: boolean;
        attachedFiles?: MervAttachedFile[];
        sourceFilePath?: string;
    }): Promise<void>;
    /**
     * Synchronous plugin row (e.g. Chai {@code Assertion.assert}) — no step screenshot; server push is best-effort async.
     */
    addPluginStepSync(testCaseStartedId: string, payload: MervPluginStepPayload): void;
    onScenarioFinish(testCaseStartedId: string, willRetry?: boolean): Promise<void>;
    finalize(): Promise<void>;
    private persistLocal;
    /**
     * Emit a Merv-Logs line for a Gherkin / plugin step, attaching a screenshot when available.
     */
    private logStepToMervLogs;
    private resolveStepScreenshotForLog;
    private captureStepScreenshot;
}

/** @deprecated Use {@link MervPlaywrightScreenshotHookParams} */
type CucumberStepScreenshotHookParams = MervPlaywrightScreenshotHookParams;
/**
 * @deprecated Use {@link MervPlaywright.screenshot} from {@code merv-client}.
 */
declare function captureCucumberStepScreenshot(page: MervPageLike | null | undefined, hookParams: CucumberStepScreenshotHookParams, options?: {
    screenshotEnabled?: boolean;
    cwd?: string;
}): Promise<void>;

export { type CucumberStepScreenshotHookParams, type MervCucumberFormatterOptions, MervCucumberSession, MervReporter, captureCucumberStepScreenshot, mervCucumberFormatter as default, mervCucumberFormatter };
